import * as THREE from './vendor/three.module.js';
// Periodic, deterministic surface: broad hand-shaped dents and fine latex grain.
export function toyMaterial(color){
 const size=512,c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d'),im=ctx.createImageData(size,size);let seed=47;const random=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};const waves=Array.from({length:25},(_,i)=>({x:1+Math.floor(random()*14),y:1+Math.floor(random()*14),p:random()*Math.PI*2,a:1/(2+i*.3)}));
 for(let y=0;y<size;y++)for(let x=0;x<size;x++){let v=0;for(const w of waves)v+=Math.sin((w.x*x+w.y*y)/size*Math.PI*2+w.p)*w.a;const h=128+v*32+(random()-.5)*5;const p=(y*size+x)*4;im.data[p]=im.data[p+1]=im.data[p+2]=h;im.data[p+3]=255}ctx.putImageData(im,0,0);const bump=new THREE.CanvasTexture(c);bump.wrapS=bump.wrapT=THREE.RepeatWrapping;bump.anisotropy=4;
 const m=new THREE.MeshPhysicalMaterial({color,roughness:.23,metalness:0,clearcoat:1,clearcoatRoughness:.08,bumpMap:bump,bumpScale:.065,clearcoatNormalMap:null,envMapIntensity:1.1,ior:1.46});return m;
}
export function toyGeometry(index){const g=new THREE.SphereGeometry(1,64,48);const p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);const d=1+.014*Math.sin(x*11+y*7+index)*Math.cos(z*9-y*4)+.009*Math.sin(y*19+z*6)*Math.sin(x*8);p.setXYZ(i,x*d,y*d,z*d)}g.computeVertexNormals();return g}
export function makeFace(kind,material){const group=new THREE.Group();let seed=[...kind].reduce((s,c)=>s+c.charCodeAt(0),0);const white=new THREE.MeshPhysicalMaterial({color:'#fff5ce',roughness:.25,clearcoat:1});const dark=new THREE.MeshPhysicalMaterial({color:'#120d1a',roughness:.15,clearcoat:1});const iris=new THREE.MeshPhysicalMaterial({color:seed%2?'#e0f354':'#73e5f4',roughness:.17,clearcoat:1});const gum=new THREE.MeshPhysicalMaterial({color:'#e765a3',roughness:.3,clearcoat:1});
function ball(x,y,z,sx,sy,sz,mat){const o=new THREE.Mesh(new THREE.SphereGeometry(1,24,18),mat);o.position.set(x,y,z);o.scale.set(sx,sy,sz);group.add(o);return o}
for(let i=0;i<2;i++){const x=i===0?-.18:.19,y=i===0?.15:.105,k=i===0?1.1+(seed%5)*.16:.65+(seed%3)*.12;ball(x,y-.015,.025,.15*k,.16*k,.09,material);ball(x,y,.09,.115*k,.13*k,.075,white);ball(x+(i?-.015:.035),y-.015,.155,.072*k,.085*k,.035,iris);ball(x+(i?-.015:.035),y-.015,.182,.044*k,.065*k,.02,dark);ball(x+.01,y+.03,.198,.018,.022,.01,white);ball(x,y-.15,.015,.14,.045,.03,material);}
ball(.015,-.015,.13,.09,.12,.1,material);ball(-.045,-.08,.16,.05,.034,.038,material);ball(.065,-.075,.17,.045,.03,.03,material);ball(.064,-.09,.197,.014,.01,.01,dark);
const points=[new THREE.Vector3(-.23,-.1,.05),new THREE.Vector3(-.12,-.22,.09),new THREE.Vector3(.08,-.23,.1),new THREE.Vector3(.24,-.13,.045)];group.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),24,.035,9,false),dark));group.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points.map(v=>new THREE.Vector3(v.x,v.y-.035,v.z))),24,.033,9,false),gum));
const tooth=ball(-.08,-.205,.13,.05+(seed%3)*.012,.065+(seed%4)*.018,.028,white);tooth.rotation.z=.22;ball(.032,-.218,.125,.033,.038,.02,white);ball(-.31,-.06,.035,.035,.028,.025,material);group.userData.resources=[white,dark,iris,gum];return group;}
export function rubberAudio(){
 let ctx,master,enabled=true,buffers=null,variant=0;
 const files=Promise.all([1,2,3].map(i=>fetch(`./audio/latex-${i}.wav`).then(r=>{if(!r.ok)throw Error('Sound unavailable');return r.arrayBuffer()}))).catch(()=>null);
 async function init(){ctx??=new(window.AudioContext||window.webkitAudioContext)();if(!master){master=ctx.createGain();master.gain.value=enabled?.65:0;master.connect(ctx.destination)}if(ctx.state==='suspended')await ctx.resume();if(!buffers){const raw=await files;if(raw)buffers=await Promise.all(raw.map(b=>ctx.decodeAudioData(b.slice(0))))}return ctx;}
 function fallback(offset=.12){const t=ctx.currentTime+offset,rate=ctx.sampleRate,duration=.78,buffer=ctx.createBuffer(1,Math.ceil(rate*duration),rate),data=buffer.getChannelData(0);let phase=0,previous=0;for(let i=0;i<data.length;i++){const time=i/rate,burst=Math.sin(Math.PI*Math.min(1,time/.78)),rub=Math.pow(Math.max(0,Math.sin(time*31+Math.sin(time*17)*1.5)),.35),noise=Math.random()*2-1;previous=.75*previous+.25*noise;const f=700+550*Math.sin(time*15)+210*Math.sin(time*81)+previous*180;phase+=Math.PI*2*f/rate;data[i]=(Math.sin(phase)+.32*Math.sin(phase*2.03)+.22*noise)*burst*rub*.16;}const source=ctx.createBufferSource();source.buffer=buffer;source.connect(master);source.start(t);}
 const popFile=fetch('./audio/pop.wav').then(r=>r.arrayBuffer()).catch(()=>null);let popBuffer=null;async function pop(){if(!enabled)return;try{await init();const raw=await popFile;if(!popBuffer&&raw)popBuffer=await ctx.decodeAudioData(raw.slice(0));if(popBuffer){const s=ctx.createBufferSource();s.buffer=popBuffer;const g=ctx.createGain();g.gain.value=.48;s.connect(g);g.connect(master);s.start()}}catch{}}
 async function twist(duration=.22){if(!enabled)return;try{await init();if(!enabled)return;if(buffers){const source=ctx.createBufferSource();source.buffer=buffers[variant++%buffers.length];source.playbackRate.value=.96+Math.random()*.08;const g=ctx.createGain(),t=ctx.currentTime+.015;g.gain.setValueAtTime(.7,t);g.gain.setValueAtTime(.7,t+duration-.025);g.gain.linearRampToValueAtTime(0,t+duration);source.connect(g);g.connect(master);source.start(t);source.stop(t+duration);source.onended=()=>g.disconnect()}else fallback()}catch{}}
 return {twist,pop,play(){twist()},setEnabled(v){enabled=v;if(master)master.gain.setTargetAtTime(v?.65:0,ctx.currentTime,.015)},get enabled(){return enabled}};
}
